import{_ as i,o as l,c as t,ae as a}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"CONTEXT.md","description":"","frontmatter":{},"headers":[],"relativePath":"CONTEXT.md","filePath":"CONTEXT.md"}'),o={name:"CONTEXT.md"};function r(s,e,n,c,d,u){return l(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="context-md" tabindex="-1">CONTEXT.md <a class="header-anchor" href="#context-md" aria-label="Permalink to &quot;CONTEXT.md&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This repository reflects a body of work situated at the intersection of:</p><ul><li>bibliometrics and research systems</li><li>knowledge infrastructure analysis</li><li>AI-assisted research workflows</li><li>emerging work on AI evaluation, verification, and structured reasoning</li></ul><p>The work is not a collection of isolated analyses, but a set of structured methods, frameworks, and tools designed to:</p><ul><li>represent research and knowledge systems</li><li>analyse their structure and dynamics</li><li>evaluate outputs, including AI-generated outputs</li></ul><hr><h2 id="core-conceptual-model" tabindex="-1">Core conceptual model <a class="header-anchor" href="#core-conceptual-model" aria-label="Permalink to &quot;Core conceptual model&quot;">​</a></h2><p>The work operates across three primary layers:</p><ol><li><p>Methods (conceptual)</p><ul><li>define how systems are represented and analysed</li><li>abstract, transferable, not tied to a specific implementation</li></ul></li><li><p>Frameworks (applied structures)</p><ul><li>structured applications of methods</li><li>introduce dimensions, workflows, and constraints</li><li>partially operational but not fully executable</li></ul></li><li><p>Tools (operational)</p><ul><li>implementations supporting specific tasks</li><li>interface-driven or programmatic</li><li>do not expose full internal logic</li></ul></li></ol><p>Additionally, there is a supporting layer:</p><ol start="4"><li>Prompt artifacts / protocols <ul><li>structured prompts used within tools and workflows</li><li>encode behaviour, evaluation logic, or style</li><li>not exposed as standalone methods</li></ul></li></ol><hr><h2 id="implemented-baseline" tabindex="-1">Implemented baseline <a class="header-anchor" href="#implemented-baseline" aria-label="Permalink to &quot;Implemented baseline&quot;">​</a></h2><p>The following components are now defined and publicly structured:</p><h3 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Method&quot;">​</a></h3><ul><li>AI metascientist</li></ul><h3 id="framework" tabindex="-1">Framework <a class="header-anchor" href="#framework" aria-label="Permalink to &quot;Framework&quot;">​</a></h3><ul><li>GRID+</li></ul><h3 id="tool" tabindex="-1">Tool <a class="header-anchor" href="#tool" aria-label="Permalink to &quot;Tool&quot;">​</a></h3><ul><li>AVA</li></ul><p>These establish a minimal working system across all three layers: method → framework → tool</p><hr><h2 id="key-distinction-method-vs-prompt-artifact" tabindex="-1">Key distinction: method vs prompt artifact <a class="header-anchor" href="#key-distinction-method-vs-prompt-artifact" aria-label="Permalink to &quot;Key distinction: method vs prompt artifact&quot;">​</a></h2><p>This distinction must be preserved:</p><ul><li><p>Methods / frameworks</p><ul><li>describe how work is done</li><li>conceptual or structured processes</li><li>reusable independently of tools</li></ul></li><li><p>Prompt artifacts (e.g. style.md)</p><ul><li>encode instructions for AI systems</li><li>operational components</li><li>belong to tooling or execution layers</li></ul></li></ul><p>Example:</p><ul><li>writing research publications → method / framework</li><li>style.md → prompt artifact</li></ul><hr><h2 id="structural-constraint" tabindex="-1">Structural constraint <a class="header-anchor" href="#structural-constraint" aria-label="Permalink to &quot;Structural constraint&quot;">​</a></h2><p>Each layer must remain distinct in both content and level of detail:</p><ul><li>methods define conceptual logic</li><li>frameworks define structured application</li><li>tools implement constrained operations</li></ul><p>Tool pages must not exceed frameworks in detail.<br> Frameworks must not expose full operational logic.</p><hr><h2 id="latent-implicit-project-categories" tabindex="-1">Latent / implicit project categories <a class="header-anchor" href="#latent-implicit-project-categories" aria-label="Permalink to &quot;Latent / implicit project categories&quot;">​</a></h2><p>Based on working patterns, the following are likely to exist as implicit assets:</p><ul><li>prompt protocol library</li><li>evaluation prompts (AI verification / validation)</li><li>classification systems (e.g. funder classification, journal categorisation)</li><li>data construction pipelines</li><li>mobility / researcher flow analysis frameworks</li><li>citation behaviour analysis methods</li><li>metric frameworks (novelty, interdisciplinarity, disruption)</li></ul><p>These are candidates for formalisation, but not all necessarily public.</p><hr><h2 id="intellectual-property-strategy" tabindex="-1">Intellectual property strategy <a class="header-anchor" href="#intellectual-property-strategy" aria-label="Permalink to &quot;Intellectual property strategy&quot;">​</a></h2><p>The work follows a layered disclosure model.</p><h3 id="public" tabindex="-1">Public <a class="header-anchor" href="#public" aria-label="Permalink to &quot;Public&quot;">​</a></h3><ul><li>conceptual methods</li><li>high-level frameworks</li><li>selected examples</li><li>partial workflows</li></ul><h3 id="partial-gated" tabindex="-1">Partial / gated <a class="header-anchor" href="#partial-gated" aria-label="Permalink to &quot;Partial / gated&quot;">​</a></h3><ul><li>structured frameworks with limited detail</li><li>worked examples</li><li>simplified logic</li></ul><h3 id="private" tabindex="-1">Private <a class="header-anchor" href="#private" aria-label="Permalink to &quot;Private&quot;">​</a></h3><ul><li>full prompt systems</li><li>optimisation heuristics</li><li>evaluation logic and scoring</li><li>orchestration / chaining</li><li>internal datasets or mappings</li></ul><p>Key principle: Do not expose anything that enables replication of most of the value.</p><hr><h2 id="positioning" tabindex="-1">Positioning <a class="header-anchor" href="#positioning" aria-label="Permalink to &quot;Positioning&quot;">​</a></h2><p>The work should be framed as:</p><ul><li>methodological, not product-driven</li><li>structural, not descriptive</li><li>rigorous, not promotional</li></ul><p>Avoid:</p><ul><li>startup language</li><li>solution framing</li><li>feature-driven descriptions</li></ul><p>Preferred framing:</p><ul><li>methods</li><li>systems</li><li>frameworks</li><li>evaluation</li></ul><hr><h2 id="long-term-direction" tabindex="-1">Long-term direction <a class="header-anchor" href="#long-term-direction" aria-label="Permalink to &quot;Long-term direction&quot;">​</a></h2><p>The work is expected to evolve from:</p><ul><li>bibliometrics and research systems</li></ul><p>toward:</p><ul><li>evaluation of knowledge systems</li><li>AI verification and safety</li><li>structured reasoning and validation</li></ul><p>This requires maintaining:</p><ul><li>domain flexibility</li><li>conceptual consistency</li><li>non-commercial tone</li></ul>',64)])])}const h=i(o,[["render",r]]);export{m as __pageData,h as default};
